// ASSET CREDITS SLOT (owner: the stage engineer, WP6).
//
// The NASA data sheet lists credits for NASA imagery and 3D models here. This package cannot know which assets the
// stage bundles, so it reads an optional file written by the stage package:
//
//     src/features/stage/credits.js
//     export const ASSET_CREDITS = [{id, title, credit, url?, licence?}];
//
// If that file exists its ASSET_CREDITS are shown verbatim; otherwise the sheet says no NASA imagery or models are bundled.
// Do not edit this file to add credits; add them in the stage package.
const found = import.meta.glob('../stage/credits.js', {eager: true});
const mod = Object.values(found)[0] || {};

/** @type {{id: string, title: string, credit: string, url?: string, licence?: string}[]} */
export const ASSET_CREDITS = Array.isArray(mod.ASSET_CREDITS) ? mod.ASSET_CREDITS : [];
